def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change = new - old
    return {
        "value": change,
        "trace": {
            "old_subscribers": old,
            "new_subscribers": new,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "subscribers"
            }
        }
    }
